@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="sentinelRef" class="infinite-scroll-sentinel">
            <div class="infinite-scroll-loading">Loading...</div>
        </div>
    }
</div>

@code {
    private ElementReference sentinelRef;
    private IJSObjectReference? moduleRef;
    private IJSObjectReference? observerRef;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? dotNetRef;
    private bool isLoading;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            moduleRef = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/InfiniteScrollList.razor.js");
            observerRef = await moduleRef.InvokeAsync<IJSObjectReference>(
                "createObserver", sentinelRef, dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnIntersecting()
    {
        if (isLoading || !HasMore)
            return;

        isLoading = true;
        await OnLoadMore.InvokeAsync();
        isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (observerRef is not null)
        {
            await observerRef.InvokeVoidAsync("disconnect");
            await observerRef.DisposeAsync();
        }
        if (moduleRef is not null)
            await moduleRef.DisposeAsync();
        dotNetRef?.Dispose();
    }
}

export function createObserver(sentinel, dotNetRef) {
    const observer = new IntersectionObserver(entries => {
        for (const entry of entries) {
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync('OnIntersecting');
            }
        }
    }, { rootMargin: '0px 0px 200px 0px' });

    observer.observe(sentinel);
    return observer;
}

